// OGL ships types only for the barrel; map the per-file deep imports onto them.
declare module 'ogl/src/core/Renderer.js' { export { Renderer } from 'ogl'; }
declare module 'ogl/src/core/Camera.js' { export { Camera } from 'ogl'; }
declare module 'ogl/src/core/Transform.js' { export { Transform } from 'ogl'; }
declare module 'ogl/src/core/Program.js' { export { Program } from 'ogl'; }
declare module 'ogl/src/core/Mesh.js' { export { Mesh } from 'ogl'; }
declare module 'ogl/src/extras/Cylinder.js' { export { Cylinder } from 'ogl'; }
